#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.039998845000000005, 0.303114475, -0.181843685], 'basis': [[0.0, 0.9997109435075289, -0.024042242642620008], [-0.20440918208548917, 0.023534603498363088, 0.9786025795578694], [0.9788855327765047, 0.004914455154078825, 0.20435009628428663]], 'axis': [-0.024042242642620008, 0.9786025795578694, 0.20435009628428663], 'zmin': -0.2036955032510046, 'zmax': 0.1956756280294273, 'profiles': [{'outer': [[-0.09229793596074597, 0.016311029509470255], [-0.09112969439503386, 0.016934989888388038], [-0.08022616704157005, 0.020849868463166884], [-0.07634518398019167, 0.021648161196223842], [-0.07531987707741085, 0.022701574795370504], [-0.06931037259442077, 0.026737099780248626], [-0.06631477682583597, 0.02909361066404904], [-0.06391490488911919, 0.031259531836519486], [-0.06027965030160099, 0.03543238543509478], [-0.0577084472473982, 0.038800748358310155], [-0.055066968435088036, 0.04190450981104311], [-0.05218952181860634, 0.044717197560094776], [-0.04912905650460486, 0.047267084287415086], [-0.04582438646726731, 0.04954860205129233], [-0.04086091041715207, 0.052376891675610805], [-0.036758729986981965, 0.054248721446756756], [-0.03243150304631291, 0.05577381701919702], [-0.030549789770298173, 0.05632459370814271], [-0.029895868425492873, 0.05912197368602538], [-0.0288841577250804, 0.06012321434827385], [-0.026822582389005433, 0.06283246311780924], [-0.025603360803960248, 0.0636760049904816], [-0.02310156561652276, 0.0639963698541134], [-0.02144793110675662, 0.0635285263008964], [-0.020974555277359207, 0.06397783086716752], [-0.018912287169426334, 0.0693066458074758], [-0.016931954084284384, 0.07097648085257201], [-0.015267872035406796, 0.07649084512221387], [-0.012267753738618867, 0.07742737136944876], [-0.010209365089567504, 0.08327418896868166], [-0.00821054641997881, 0.08244012117915295], [-0.003671663833320898, 0.08544814105558061], [-0.0013086723389203769, 0.08659172252579707], [0.002305474794576065, 0.08352030411254564], [0.009795061124876455, 0.07302920575937383], [0.01770310803786866, 0.0643126997611117], [0.02577828621436729, 0.05472064359775014], [0.030727619001453613, 0.04534948654527652], [0.033862973928071846, 0.03821046661917866], [0.03581010649767488, 0.03413561870087344], [0.0385395112183312, 0.026417192904234436], [0.04064192469173236, 0.020739590927288557], [0.04250264919498784, 0.018473923660107312], [0.04649195192910683, 0.014461878294764679], [0.04978243808761543, 0.011779023701901823], [0.05344849904626171, 0.009109511678129985], [0.06124866092737945, 0.0040281449458652125], [0.063114797471429, 0.0023892784936260718], [0.06890133363389855, -0.0017599383477099131], [0.07149418847848182, -0.005462969434898058], [0.07300158208319234, -0.00700819284408147], [0.07292808626181961, -0.011244411276667117], [0.06764366316365036, -0.015308734101175472], [0.055127459833053595, -0.018988416992999448], [0.04222460326525826, -0.023040400639237017], [0.03919250931344767, -0.02426741014742055], [0.03251333060724575, -0.027170329798815254], [0.031962531725404274, -0.028285165800873115], [0.029124838544266476, -0.031031458473300973], [0.024676395234596554, -0.033573092957735216], [0.0185123443322974, -0.03584240100693591], [0.015000653249793947, -0.03757910118278568], [0.010632433710489199, -0.039317557235377484], [0.005321858979924822, -0.04115891984543148], [-0.002380695371300204, -0.044452645329063255], [-0.01206611037395528, -0.05338507877513458], [-0.020901042602357426, -0.06876266945409712], [-0.027554538898024592, -0.07896023345911296], [-0.03291379380354469, -0.08186199226955339], [-0.03755039354134621, -0.07862925599394016], [-0.04188851876923618, -0.07261214219010584], [-0.04525378583786193, -0.05856511130269814], [-0.0474821396362521, -0.04303228821553582], [-0.050312828625032766, -0.03383769372391552], [-0.05150738326036513, -0.03186566562278609], [-0.05453129977868496, -0.027909310220898965], [-0.059403624600198955, -0.02441785246917001], [-0.07079569023335024, -0.018005543947182574], [-0.07904573407428354, -0.011875486317519706], [-0.09657774603589232, -0.002697919262689387], [-0.0976919914619618, 0.0021806776781872032], [-0.09246145182896945, 0.005564460632109052], [-0.09444395434969123, 0.006942132903327364], [-0.09576566143791912, 0.012275596773429041]], 'holes': []}], 'simplify_tolerance': 3.4138714709030827e-05, 'sketch_entity_count': 93}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
